"use client";

import { useEffect, useState } from "react";
import { walletService } from "@/lib/services/wallet-service";
import { toast } from "sonner";
import { useAuth } from "@/app/context/auth-context";
import { PERMISSIONS } from "@/lib/permissions";
import { PageHeader } from "@/components/layouts/page-header";
import { DashboardPagination } from "@/components/tables/dashboard-pagination";
import { Search, Wallet, Eye } from "lucide-react";
import { Input } from "@/components/ui/input";
import { useRouter } from "next/navigation";
import { Badge } from "@/components/ui/badge";

export default function WalletsPage() {
    const router = useRouter();
    const { hasPermission } = useAuth();

    const [wallets, setWallets] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState("");
    const [page, setPage] = useState(1);
    const [limit, setLimit] = useState(10);
    const [total, setTotal] = useState(0);
    const [totalPages, setTotalPages] = useState(1);

    useEffect(() => {
        loadWallets();
    }, [page, limit, searchQuery]);

    const loadWallets = async () => {
        try {
            setLoading(true);
            const response = await walletService.getAllWallets({
                page,
                limit,
                q: searchQuery || undefined,
            });

            if (response && response.success) {
                setWallets(response.data);
                setTotal(response.total);
                setTotalPages(response.totalPages);
            }
        } catch (err) {
            toast.error("Failed to load wallets");
        } finally {
            setLoading(false);
        }
    };

    if (!hasPermission(PERMISSIONS.REVENUE_VIEW)) {
        return (
            <div className="p-6 text-center text-red-500 font-semibold">
                Access Denied: Missing REVENUE_VIEW permission
            </div>
        );
    }

    return (
        <div className="p-6 space-y-6">
            <PageHeader
                title="Parking Wallets"
                description="Monitor parking wallet balances and commission accounts."
            >
                <div className="relative w-full lg:w-72">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
                    <Input
                        placeholder="Search parking name..."
                        className="pl-10 h-11 rounded-xl border-slate-200"
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                    />
                </div>
            </PageHeader>

            <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-left border-collapse">
                        <thead>
                            <tr className="bg-slate-50/50 border-b border-slate-100">
                                <th className="px-6 py-4 font-bold text-slate-600">Parking Name</th>
                                <th className="px-6 py-4 font-bold text-slate-600">Balance</th>
                                <th className="px-6 py-4 font-bold text-slate-600">Currency</th>
                                <th className="px-6 py-4 font-bold text-slate-600">Status</th>
                                <th className="px-6 py-4 font-bold text-slate-600 text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody>
                            {loading ? (
                                Array.from({ length: 5 }).map((_, i) => (
                                    <tr key={i} className="animate-pulse border-b border-slate-50">
                                        <td className="px-6 py-4"><div className="h-5 w-40 bg-slate-100 rounded" /></td>
                                        <td className="px-6 py-4"><div className="h-5 w-24 bg-slate-100 rounded" /></td>
                                        <td className="px-6 py-4"><div className="h-5 w-12 bg-slate-100 rounded" /></td>
                                        <td className="px-6 py-4"><div className="h-5 w-16 bg-slate-100 rounded" /></td>
                                        <td className="px-6 py-4"><div className="h-5 w-8 ml-auto bg-slate-100 rounded" /></td>
                                    </tr>
                                ))
                            ) : wallets.length === 0 ? (
                                <tr>
                                    <td colSpan={5} className="px-6 py-12 text-center text-slate-500 font-medium">
                                        No wallets found.
                                    </td>
                                </tr>
                            ) : (
                                wallets.map((wallet) => (
                                    <tr key={wallet.id} className="border-b border-slate-50 hover:bg-slate-50/50 transition-colors">
                                        <td className="px-6 py-4">
                                            <div className="font-semibold text-slate-900">{wallet.parking?.name || "Unknown"}</div>
                                            <div className="text-xs text-slate-500">{wallet.parking?.parkingCode}</div>
                                        </td>
                                        <td className="px-6 py-4 text-lg font-bold text-slate-900">
                                            {wallet.balance.toLocaleString()}
                                        </td>
                                        <td className="px-6 py-4 font-medium text-slate-600">
                                            {wallet.currency}
                                        </td>
                                        <td className="px-6 py-4">
                                            <Badge className={wallet.isActive ? "bg-green-100 text-green-700" : "bg-red-100 text-red-700"} variant="secondary">
                                                {wallet.isActive ? "Active" : "Inactive"}
                                            </Badge>
                                        </td>
                                        <td className="px-6 py-4 text-right">
                                            <button
                                                onClick={() => router.push(`/dashboard/parkings/${wallet.ownerId}`)}
                                                className="p-2 hover:bg-blue-50 text-blue-600 rounded-lg transition-colors group"
                                                title="View Parking Detail"
                                            >
                                                <Eye size={20} />
                                            </button>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>
            </div>

            <DashboardPagination
                page={page}
                totalPages={totalPages}
                total={total}
                onPageChange={setPage}
                limit={limit}
                onLimitChange={setLimit}
            />
        </div>
    );
}
